// Define a simple Matrix struct to represent the result
#[derive(Debug, PartialEq, Eq)]
pub struct Matrix<T> {
    data: Vec<Vec<T>>,
    rows: usize,
    cols: usize,
}

impl<T> Matrix<T> {
    // Helper method to create a new matrix
    fn new(data: Vec<Vec<T>>, rows: usize, cols: usize) -> Self {
        Self { data, rows, cols }
    }
}

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract dimensions from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;
    
    // Get the length of the input array
    let len = a.len();
    
    // Create the result matrix
    let mut result = Vec::with_capacity(r);
    
    if r == len {
        // Treat as column vector: each element of a becomes a row
        // Each row contains the same element repeated c times
        for &elem in &a {
            let row = vec![elem; c];
            result.push(row);
        }
    } else if c == len {
        // Treat as row vector: the entire array is repeated for each row
        for _ in 0..r {
            result.push(a.clone());
        }
    } else {
        // According to the problem statement, this case shouldn't happen
        // because at least one dimension must match the array length
        panic!("Neither dimension matches the array length");
    }
    
    Matrix::new(result, r, c)
}